<?php
/**
 * The Magazine theme's bootstrap.
 *
 * @package Magazine
 */

namespace Magazine;

defined( 'ABSPATH' ) || exit;

// Classes load through Composer's PSR-4 autoloader (Magazine\ → inc/), generated by `npm run build`.
if ( ! is_readable( __DIR__ . '/vendor/autoload.php' ) ) {
	add_action(
		'admin_notices',
		function () {
			printf( '<div class="notice notice-error"><p>%s</p></div>', esc_html__( 'The Magazine theme is not built: run npm run build.', 'magazine' ) );
		}
	);
	return;
}
require_once __DIR__ . '/vendor/autoload.php';

( new Theme() )->boot();
